import {player, clock} from './engine.mjs';
import {playerPulse} from './player-pulse.mjs';

export function renderPulsePanel(events,seed,playerId,asOf) {
  const methodOpen=document.querySelector('#pulse-panel details')?.open;
  const pulse=playerPulse(events,seed,playerId,asOf), p=player(playerId), current=pulse.current;
  const fmt=n=>n===null?'—':n.toFixed(1), sign=n=>n===null?'—':`${n>0?'+':''}${n.toFixed(1)}`;
  const compare=(label,baseline)=>`<article class="pulse-stat"><span>${label}</span><strong>${fmt(baseline.median)}<small> / 100</small></strong><p>${baseline.matches} frühere Spiele · Median</p><b>${sign(baseline.delta)} Punkte heute</b></article>`;
  const trace=[{time_s:0,index:50}]; for(const c of current.contributions){trace.push({time_s:c.time_s,index:trace.at(-1).index},c);}
  const xy=c=>`${20+c.time_s/5400*660},${125-c.index}`;
  const lines=[['Saison',pulse.season.median,'#8364c6'],['Karriere',pulse.career.median,'#77847a']].filter(([,n])=>n!==null).map(([name,n,color])=>`<path d="M20 ${125-n}H680" stroke="${color}" stroke-dasharray="5 5"/>`).join('');
  document.getElementById('pulse-panel').innerHTML=`<div class="pulse-heading"><div><div class="eyebrow">PLAYER PULSE · ALLE DATEN SYNTHETISCH</div><h2>${p.number} · ${p.name} <span>${p.role}</span></h2><p>Dein Spieler, jede Aktion erklärt. Vergleich bis ${clock(asOf)}.</p></div><button class="button secondary" id="pulse-export">Spielerbericht ↓</button></div><div class="pulse-stats"><article class="pulse-stat current"><span>Live-Index · ${clock(asOf)}</span><strong>${fmt(current.index)}<small> / 100</small></strong><p>${current.supported?`${current.rated_events} gewertete Aktionen · ${current.provisional?'vorläufig':'heuristisch'}`:'Torwartwertung nicht verfügbar'}</p><b>${current.supported?'Startwert 50 + Aktionsbeiträge':'Paraden und Torwartaktionen fehlen'}</b></article>${compare('Synthetische Saison · S4',pulse.season)}${compare('Synthetische Karriere · S1–S4',pulse.career)}</div><div class="pulse-detail"><div><h3>Sein Verlauf in diesem Spiel</h3><svg class="pulse-chart" viewBox="0 0 700 150" role="img" aria-label="Indexverlauf bis ${clock(asOf)}, Saisonmedian ${fmt(pulse.season.median)}, Karrieremedian ${fmt(pulse.career.median)}"><path d="M20 25V125H680" stroke="#d7dfd1" fill="none"/>${current.supported?lines:''}${current.index!==null?`<polyline points="${trace.map(xy).join(' ')} ${20+asOf/5400*660},${125-current.index}" fill="none" stroke="#315e29" stroke-width="3"/>`:''}<text x="20" y="145" font-size="10">0′</text><text x="340" y="145" font-size="10">45′</text><text x="660" y="145" font-size="10">90′</text></svg><p class="pulse-note"><span style="color:#8364c6">━ Saison</span> · <span style="color:#77847a">━ Karriere</span> · <span style="color:#315e29">━ Live-Index</span><br>Linien: historische Medianwerte zum aktuellen Zeitpunkt. 48 abgeschlossene fiktive Spiele; die Saison ist Teil der Karriere. Keine echten Leistungsdaten.</p></div><div><h3>Warum ändert sich der Index?</h3><div class="pulse-actions">${current.contributions.slice(-4).reverse().map(c=>`<button data-pulse-event="${c.event_id}"><time>${clock(c.time_s)}</time><span>${c.label}</span><strong class="${c.delta<0?'negative':''}">${sign(c.delta)}</strong></button>`).join('')||'<p>Noch keine auswertbaren Aktionen für diesen Spieler.</p>'}</div><p class="pulse-note">Eine Aktion anklicken, um Berechnung und Ereignisbeleg zu prüfen.</p></div></div><details class="pulse-method" ${methodOpen?'open':''}><summary>Wie wird der Index berechnet?</summary><p>Der Index beginnt bei 50. Erfolgreicher Pass: +0,2 + Vorwärtsmeter / 40 + Passschwierigkeit / 200. Fehlpass: −0,8. Abschluss: +2 × Shot Quality, Tor zusätzlich +5. Druckaktion: +0,6 für Abwehr / DM, sonst +0,4. Gewonnener Tackle: +1,4 für Abwehr / DM, sonst +1; verlorener Tackle: −0,6. Ballverlust: −1,5. Einwurf: 0. Die Summe wird auf 0–100 begrenzt und auf eine Nachkommastelle gerundet.</p><p>Identische Formel, derselbe Spieler und dieselbe Spielminute für alle Vergleiche. Unter fünf gewerteten Aktionen ist der Wert vorläufig. Dies ist ein nicht kalibrierter Aktivitäts- und Beitragsindex; keine objektive Spielernote, Fitnessmessung oder Prognose. Alle historischen Einsätze dauern im Modell 90 Minuten ohne Auswechslungen. Laufwege beeinflussen den Index nicht.</p></details>`;
  return pulse;
}
